a = list(map(int, input().split()))
t = int(input())
low, high = 0, len(a)
while low <= high:
    mid = (low + high) // 2
    if a[mid] < t:
        low = mid + 1
    else:
        high = mid
print(low)

text = input().split()
counts = {}
for w in text:
    counts[w] = counts.get(w, 0) + 1
best = None
for w in counts:
    if best is None or counts[w] > counts[best]:
        best = w
print(best)

n = int(input())
acc = 0
for _ in range(n - 1):
    op, x = input().split()
    if op == 'ADD':
        acc += int(x)
    else:
        acc *= int(x)
print(acc)

